String dartMapEntries(Map<String, String> map) {
  final buf = StringBuffer();
  for (final e in map.entries) {
    final v = e.value.replaceAll("'", "\\'");
    buf.writeln("      '${e.key}': '$v',");
  }
  return buf.toString();
}

